FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  19 Oktober 2024                 #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  19 Oktober 2024                 #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated during October 2015\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 19 Oktober 2024\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Meshing a pipe with layers (90 degree)${NC}\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"` \n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "     Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    'cad/salome.py': '# -*- coding: utf-8 -*-\n\n###\n### This file is generated automatically by SALOME v7.5.1 with dump python functionality\n###\n\nimport sys\nimport salome\n\nsalome.salome_init()\ntheStudy = salome.myStudy\n\nimport salome_notebook\nnotebook = salome_notebook.NoteBook(theStudy)\nsys.path.insert( 0, r\'/home/shorty/OpenFOAM/shorty-2.3.1/run/meshing/90DegreePipe/cad\')\n\n###\n### GEOM component\n###\n\nimport GEOM\nfrom salome.geom import geomBuilder\nimport math\nimport SALOMEDS\n\n\ngeompy = geomBuilder.New(theStudy)\n\nO = geompy.MakeVertex(0, 0, 0)\nOX = geompy.MakeVectorDXDYDZ(1, 0, 0)\nOY = geompy.MakeVectorDXDYDZ(0, 1, 0)\nOZ = geompy.MakeVectorDXDYDZ(0, 0, 1)\nCylinder_1 = geompy.MakeCylinderRH(0.02, 0.2)\n[Face_1] = geompy.SubShapes(Cylinder_1, [10])\nVertex_1 = geompy.MakeVertex(0.04, -0, 0.2)\nVertex_2 = geompy.MakeVertex(0.04, 0.02, 0.2)\nLine_1 = geompy.MakeLineTwoPnt(Vertex_2, Vertex_1)\nRevolution_1 = geompy.MakeRevolution(Face_1, Line_1, -90*math.pi/180.0)\n[Face_2] = geompy.SubShapes(Revolution_1, [12])\nExtrusion_1 = geompy.MakePrismVecH(Face_2, OX, 0.2)\npipe = geompy.MakeFuseList([Cylinder_1, Revolution_1, Extrusion_1], True, True)\ninlet = geompy.CreateGroup(pipe, geompy.ShapeType["FACE"])\ngeompy.UnionIDs(inlet, [15])\noutlet = geompy.CreateGroup(pipe, geompy.ShapeType["FACE"])\ngeompy.UnionIDs(outlet, [22])\nwall = geompy.CreateGroup(pipe, geompy.ShapeType["FACE"])\ngeompy.UnionIDs(wall, [10, 3, 17])\nBounding_Box_1 = geompy.MakeBoundingBox(pipe, True)\ngeomObj_1 = geompy.MakeCDG(Bounding_Box_1)\nPoint_1 = geompy.MakeCDG(Bounding_Box_1)\nbgMesh = geompy.MakeScaleTransform(Bounding_Box_1, Point_1, 2)\ngeompy.addToStudy( O, \'O\' )\ngeompy.addToStudy( OX, \'OX\' )\ngeompy.addToStudy( OY, \'OY\' )\ngeompy.addToStudy( OZ, \'OZ\' )\ngeompy.addToStudy( Cylinder_1, \'Cylinder_1\' )\ngeompy.addToStudy( Vertex_1, \'Vertex_1\' )\ngeompy.addToStudyInFather( Cylinder_1, Face_1, \'Face_1\' )\ngeompy.addToStudy( Vertex_2, \'Vertex_2\' )\ngeompy.addToStudy( Line_1, \'Line_1\' )\ngeompy.addToStudy( Revolution_1, \'Revolution_1\' )\ngeompy.addToStudyInFather( Revolution_1, Face_2, \'Face_2\' )\ngeompy.addToStudy( Extrusion_1, \'Extrusion_1\' )\ngeompy.addToStudy( pipe, \'pipe\' )\ngeompy.addToStudyInFather( pipe, inlet, \'inlet\' )\ngeompy.addToStudyInFather( pipe, outlet, \'outlet\' )\ngeompy.addToStudyInFather( pipe, wall, \'wall\' )\ngeompy.addToStudy( Bounding_Box_1, \'Bounding Box_1\' )\ngeompy.addToStudy( Point_1, \'Point_1\' )\ngeompy.addToStudy( bgMesh, \'bgMesh\' )\n\n###\n### SMESH component\n###\n\nimport  SMESH, SALOMEDS\nfrom salome.smesh import smeshBuilder\n\nsmesh = smeshBuilder.New(theStudy)\ninlet_1 = smesh.Mesh(inlet)\nRegular_1D = inlet_1.Segment()\nLocal_Length_1 = Regular_1D.LocalLength(0.002,[],1e-07)\nNETGEN_2D_ONLY = inlet_1.Triangle(algo=smeshBuilder.NETGEN_2D)\nisDone = inlet_1.Compute()\noutlet_1 = smesh.Mesh(outlet)\nstatus = outlet_1.AddHypothesis(Local_Length_1)\nstatus = outlet_1.AddHypothesis(Regular_1D)\nstatus = outlet_1.AddHypothesis(NETGEN_2D_ONLY)\nisDone = outlet_1.Compute()\nwall_1 = smesh.Mesh(wall)\nstatus = wall_1.AddHypothesis(Local_Length_1)\nstatus = wall_1.AddHypothesis(Regular_1D)\nstatus = wall_1.AddHypothesis(NETGEN_2D_ONLY)\nisDone = wall_1.Compute()\nwall_1.ExportSTL( r\'/home/shorty/OpenFOAM/shorty-2.3.1/run/meshing/90DegreePipe/cad/stl/wall.stl\', 1 )\noutlet_1.ExportSTL( r\'/home/shorty/OpenFOAM/shorty-2.3.1/run/meshing/90DegreePipe/cad/stl/outlet.stl\', 1 )\ninlet_1.ExportSTL( r\'/home/shorty/OpenFOAM/shorty-2.3.1/run/meshing/90DegreePipe/cad/stl/inlet.stl\', 1 )\nLocal_Length_2 = smesh.CreateHypothesis(\'LocalLength\')\nbgMesh_1 = smesh.Mesh(bgMesh)\nstatus = bgMesh_1.AddHypothesis(Local_Length_2)\nstatus = bgMesh_1.AddHypothesis(Regular_1D)\nQuadrangle_2D = bgMesh_1.Quadrangle(algo=smeshBuilder.QUADRANGLE)\nHexa_3D = bgMesh_1.Hexahedron(algo=smeshBuilder.Hexa)\nLocal_Length_2.SetLength( 0.005 )\nLocal_Length_2.SetPrecision( 1e-07 )\nisDone = bgMesh_1.Compute()\nbgMesh_1.ExportUNV( r\'/home/shorty/OpenFOAM/shorty-2.3.1/run/meshing/90DegreePipe/cad/backgroundMesh.unv\' )\n\n\n## Set names of Mesh objects\nsmesh.SetName(Regular_1D.GetAlgorithm(), \'Regular_1D\')\nsmesh.SetName(Quadrangle_2D.GetAlgorithm(), \'Quadrangle_2D\')\nsmesh.SetName(NETGEN_2D_ONLY.GetAlgorithm(), \'NETGEN_2D_ONLY\')\nsmesh.SetName(Hexa_3D.GetAlgorithm(), \'Hexa_3D\')\nsmesh.SetName(Local_Length_2, \'Local Length_2\')\nsmesh.SetName(Local_Length_1, \'Local Length_1\')\nsmesh.SetName(inlet_1.GetMesh(), \'inlet\')\nsmesh.SetName(wall_1.GetMesh(), \'wall\')\nsmesh.SetName(outlet_1.GetMesh(), \'outlet\')\nsmesh.SetName(bgMesh_1.GetMesh(), \'bgMesh\')\n\n\nif salome.sg.hasDesktop():\n  salome.sg.updateObjBrowser(1)\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: October 2015                    #\n# Topic:                                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -f constant/triSurface/*.eMesh paraview.foam\nrm -rf 0 log* constant/extend*\n\n\n#-------------------------------------------------------------------------------\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------#\n# Contributor: Tobias Holzmann                    #\n# Updated on:  19 Oktober 2024                    #\n#-------------------------------------------------#\n# Topic:       Meshing a pipe (90 degree)         #\n# OpenFOAM:    version 12 (Foundation)             #\n#-------------------------------------------------#\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n#-------------------------------------------------#\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create feature edges"\nsurfaceFeatures >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create background mesh"\nideasUnvToFoam cad/backgroundMesh.unv >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Meshing with snappyHexMesh"\nsnappyHexMesh >> logMeshing\ntouch paraview.foam\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\\n\n"\n\n\n#------------------------------------------------------------------------------\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     simpleFoam;\n\nstartFrom       startTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         500;\n\ndeltaT          1;\n\nwriteControl    timeStep;\n\nwriteInterval   100;\n\npurgeWrite      0;\n\nwriteFormat     binary;\n\nwritePrecision  6;\n\nwriteCompression uncompressed;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable true;\n\n\n// ************************************************************************* //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default         steadyState;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n    grad(U)         cellLimited Gauss linear 1;\n}\n\ndivSchemes\n{\n    default         none;\n    div(phi,U)      bounded Gauss linearUpwindV grad(U);\n    div(phi,k)      bounded Gauss upwind;\n    div(phi,omega)  bounded Gauss upwind;\n    div((nuEff*dev(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear corrected;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         corrected;\n}\n\nfluxRequired\n{\n    default         no;\n    p;\n}\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    p\n    {\n        solver           GAMG;\n        tolerance        1e-7;\n        relTol           0.01;\n        smoother         GaussSeidel;\n        nPreSweeps       0;\n        nPostSweeps      2;\n        cacheAgglomeration on;\n        agglomerator     faceAreaPair;\n        nCellsInCoarsestLevel 10;\n        mergeLevels      1;\n    }\n\n    U\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n\n    k\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n\n    omega\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n}\n\nSIMPLE\n{\n    nNonOrthogonalCorrectors 0;\n}\n\npotentialFlow\n{\n    nNonOrthogonalCorrectors 10;\n}\n\nrelaxationFactors\n{\n    fields\n    {\n        p               0.3;\n    }\n    equations\n    {\n        U               0.7;\n        k               0.7;\n        omega           0.7;\n    }\n}\n\ncache\n{\n    grad(U);\n}\n\n// ************************************************************************* //\n',
    'system/meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Include defaults parameters from master dictionary\n#includeEtc "caseDicts/mesh/generation/meshQualityDict"\n\n//- minFaceWeight (0 -> 0.5)\nminFaceWeight 0.02;\n\n\n// ************************************************************************* //\n',
    'system/snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      snappyHexMeshDict;\n}\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Which of the steps to run\ncastellatedMesh true;\nsnap            true;\naddLayers       true;\n\n\n// Geometry. Definition of all surfaces. All surfaces are of class\n// searchableSurface.\n// Surfaces are used\n// - to specify refinement for any mesh cell intersecting it\n// - to specify refinement for any mesh cell inside/outside/near\n// - to \'snap\' the mesh boundary to the surface\ngeometry\n{\n    regionSTL\n    {\n        file "regionSTL.stl";\n        type triSurfaceMesh;\n        regions\n        {\n\n            inlet   { name inlet; }\n            outlet  { name outlet; }\n            wall    { name wall; }\n        }\n    }\n};\n\n\n\n// Settings for the castellatedMesh generation.\ncastellatedMeshControls\n{\n\n    // Refinement parameters\n    // ~~~~~~~~~~~~~~~~~~~~~\n\n    // If local number of cells is >= maxLocalCells on any processor\n    // switches from from refinement followed by balancing\n    // (current method) to (weighted) balancing before refinement.\n    maxLocalCells 5000000;\n\n    // Overall cell limit (approximately). Refinement will stop immediately\n    // upon reaching this number so a refinement level might not complete.\n    // Note that this is the number of cells before removing the part which\n    // is not \'visible\' from the keepPoint. The final number of cells might\n    // actually be a lot less.\n    maxGlobalCells 5000000;\n\n    // The surface refinement loop might spend lots of iterations refining just a\n    // few cells. This setting will cause refinement to stop if <= minimumRefine\n    // are selected for refinement. Note: it will at least do one iteration\n    // (unless the number of cells to refine is 0)\n    minRefinementCells 0;\n\n    // Number of buffer layers between different levels.\n    // 1 means normal 2:1 refinement restriction, larger means slower\n    // refinement.\n    nCellsBetweenLevels 5;\n\n\n\n    // Explicit feature edge refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies a level for any cell intersected by its edges.\n    // This is a featureEdgeMesh, read from constant/triSurface for now.\n    features\n    (\n        {\n            file "regionSTL.eMesh";\n            level 0;\n        }\n    );\n\n\n\n    // Surface based refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies two levels for every surface. The first is the minimum level,\n    // every cell intersecting a surface gets refined up to the minimum level.\n    // The second level is the maximum level. Cells that \'see\' multiple\n    // intersections where the intersections make an\n    // angle > resolveFeatureAngle get refined up to the maximum level.\n\n    refinementSurfaces\n    {\n        regionSTL\n        {\n            // Surface-wise min and max refinement level\n            level (0 0);\n            regions\n            {\n                inlet   { level (0 0); }\n                outlet  { level (0 0); }\n                wall    { level (2 2); }\n            }\n        }\n    }\n\n    resolveFeatureAngle 30;\n\n\n    // Region-wise refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies refinement level for cells in relation to a surface. One of\n    // three modes\n    // - distance. \'levels\' specifies per distance to the surface the\n    //   wanted refinement level. The distances need to be specified in\n    //   descending order.\n    // - inside. \'levels\' is only one entry and only the level is used. All\n    //   cells inside the surface get refined up to the level. The surface\n    //   needs to be closed for this to be possible.\n    // - outside. Same but cells outside.\n\n    refinementRegions\n    {\n    }\n\n\n    // Mesh selection\n    // ~~~~~~~~~~~~~~\n\n    // After refinement patches get added for all refinementSurfaces and\n    // all cells intersecting the surfaces get put into these patches. The\n    // section reachable from the locationInMesh is kept.\n    // NOTE: This point should never be on a face, always inside a cell, even\n    // after refinement.\n    // This is an outside point locationInMesh (-0.033 -0.033 0.0033);\n    locationInMesh (0 0 0.001); // Inside point\n\n    // Whether any faceZones (as specified in the refinementSurfaces)\n    // are only on the boundary of corresponding cellZones or also allow\n    // free-standing zone faces. Not used if there are no faceZones.\n    allowFreeStandingZoneFaces false;\n}\n\n\n\n// Settings for the snapping.\nsnapControls\n{\n    //- Number of patch smoothing iterations before finding correspondence\n    //  to surface\n    nSmoothPatch 3;\n\n    //- Relative distance for points to be attracted by surface feature point\n    //  or edge. True distance is this factor times local\n    //  maximum edge length.\n    tolerance 1.0;\n\n    //- Number of mesh displacement relaxation iterations.\n    nSolveIter 100;\n\n    //- Maximum number of snapping relaxation iterations. Should stop\n    //  before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n    // Feature snapping\n\n        //- Number of feature edge snapping iterations.\n        //  Leave out altogether to disable.\n        nFeatureSnapIter 5;\n\n        //- Detect (geometric) features by sampling the surface\n        implicitFeatureSnap false;\n\n        //- Use castellatedMeshControls::features\n        explicitFeatureSnap true;\n\n        //- Detect features between multiple surfaces\n        //  (only for explicitFeatureSnap, default = false)\n        multiRegionFeatureSnap false;\n}\n\n\n\n// Settings for the layer addition.\naddLayersControls\n{\n    // Are the thickness parameters below relative to the undistorted\n    // size of the refined cell outside layer (true) or absolute sizes (false).\n    relativeSizes false;\n\n    // Per final patch (so not geometry!) the layer information\n    layers\n    {\n        wall\n        {\n            nSurfaceLayers 8;\n        }\n    }\n\n    // Expansion factor for layer mesh\n    expansionRatio 1.2;\n\n\n    // Wanted thickness of final added cell layer. If multiple layers\n    // is the thickness of the layer furthest away from the wall.\n    // See relativeSizes parameter.\n    finalLayerThickness 0.001;\n\n    // Minimum thickness of cell layer. If for any reason layer\n    // cannot be above minThickness do not add layer.\n    // See relativeSizes parameter.\n    minThickness 0.0005;\n\n    // If points get not extruded do nGrow layers of connected faces that are\n    // also not grown. This helps convergence of the layer addition process\n    // close to features.\n    nGrow 0;\n\n\n    // Advanced settings\n\n    // When not to extrude surface. 0 is flat surface, 90 is when two faces\n    // are perpendicular\n    featureAngle 80;\n\n    // Maximum number of snapping relaxation iterations. Should stop\n    // before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n    // Number of smoothing iterations of surface normals\n    nSmoothSurfaceNormals 1;\n\n    // Number of smoothing iterations of interior mesh movement direction\n    nSmoothNormals 3;\n\n    // Smooth layer thickness over surface patches\n    nSmoothThickness 10;\n\n    // Stop layer growth on highly warped cells\n    maxFaceThicknessRatio 0.5;\n\n    // Reduce layer growth where ratio thickness to medial\n    // distance is large\n    maxThicknessToMedialRatio 0.3;\n\n    // Angle used to pick up medial axis points\n    minMedianAxisAngle 90;\n\n    // Create buffer region for new layer terminations\n    nBufferCellsNoExtrude 0;\n\n\n    // Overall max number of layer addition iterations. The mesher will exit\n    // if it reaches this number of iterations; possibly with an illegal\n    // mesh.\n    nLayerIter 50;\n\n    // Max number of iterations after which relaxed meshQuality controls\n    // get used. Up to nRelaxIter it uses the settings in meshQualityControls,\n    // after nRelaxIter it uses the values in meshQualityControls::relaxed.\n    nRelaxedIter 20;\n}\n\n\n\n// Generic mesh quality settings. At any undoable phase these determine\n// where to undo.\nmeshQualityControls\n{\n    #include "meshQualityDict"\n\n    // Optional : some meshing phases allow usage of relaxed rules.\n    // See e.g. addLayersControls::nRelaxedIter.\n    relaxed\n    {\n        //- Maximum non-orthogonality allowed. Set to 180 to disable.\n        maxNonOrtho 65;\n    }\n\n    // Advanced\n\n    //- Number of error distribution iterations\n    nSmoothScale 4;\n    //- amount to scale back displacement at error points\n    errorReduction 0.75;\n}\n\n\n// Advanced\n\n// Write flags\nwriteFlags\n(\n    scalarLevels    // write volScalarField with cellLevel for postprocessing\n    layerSets       // write cellSets, faceSets of faces in layer\n    layerFields     // write volScalarField for layer coverage\n);\n\n\n// Merge tolerance. Is fraction of overall bounding box of initial mesh.\n// Note: the write tolerance needs to be higher than this.\nmergeTolerance 1E-6;\n\n\n// ************************************************************************* //\n',
    'system/surfaceFeaturesDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      surfaceFeatureExtractDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nregionSTL\n{\n    // The files of which you want to extract the features\n    // Located in constant/triSurface\n    surfaces\n    (\n        "regionSTL.stl"\n    );\n\n    //- Since 6.x\n    //  Needed especially for bad triangulations.\n    //  Always check your feature edge mesh\n    trimFeatures\n    {\n        //- Feature edges that contains less than \'minElem\' of edges are\n        //  removed automatically\n        minElem 5;\n\n        //- Remove feature edges that are less than the total length of [m]\n        minLen  0.001;\n    }\n\n    //- This is the angle between faces\n    includedAngle       150;\n\n    //- Since 6.x\n    //  Outputs the curvature of the surface\n    //curvature           no;\n\n    //- Since 6.x\n    //  Outputs the priximity of points and edges to each other\n    //featureProximity    no;\n\n    //- Since 6.x\n    //  The maximum search distance to use, when looking for other feature\n    //  points and edges\n    //maxFeatureProximity  1;\n\n    //- Write features for post processing into *.obj format\n    //  *.obj can be read by ParaView\n    writeObj            yes;\n\n    //- Write the surface proximity and curvature to the VTK format\n    writeVTK            no;\n}\n\n\n// ************************************************************************* //\n',
}
